insert into public.training_scenarios_v22(stable_key,title,scenario_type,role_focus,intro,prompt,decisions,debrief,visuals,media,sources) values
('v22:workers-general','Formazione generale: chi fa cosa quando il rischio cambia','decision','lavoratore','Una situazione normale cambia: una protezione è fuori servizio e la produzione dovrebbe continuare.','Individua pericolo, ruolo, limite della tua azione, segnalazione e condizione che consente la ripresa.','[{"choice":"Fermo il punto critico e attivo il flusso previsto fino al ripristino verificato","effect":"Ruoli e prevenzione diventano operativi"},{"choice":"Compenso con maggiore attenzione","effect":"Il sistema resta degradato"}]'::jsonb,'{"questions":["Chi deve essere informato?","Che cosa può decidere il lavoratore?","Chi verifica il ripristino?"]}'::jsonb,'[{"asset":"organigramma-sicurezza.svg"},{"asset":"stop-segnala-ripristina.svg"},{"asset":"piramide-pericoli.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - principi di sicurezza e prevenzione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb),
('v22:workers-low','Rischio basso: routine, VDT, spazi e piccole anomalie','hazard_spotting','lavoratore rischio basso','Una giornata di ufficio/servizio accumula posture, passaggi ostruiti, cavi, stress e una piccola anomalia elettrica.','Trova ciò che può diventare incidente o disturbo cronico e ordina le correzioni per efficacia.','[{"choice":"Correggo ambiente e organizzazione, poi uso comportamenti individuali come complemento","effect":"Prevenzione sistemica"},{"choice":"Mi concentro solo su postura e attenzione personale","effect":"Molti fattori restano invariati"}]'::jsonb,'{"questions":["Quale rischio è immediato?","Quale è cumulativo?","Che cosa richiede manutenzione e non comportamento?"]}'::jsonb,'[{"asset":"idea-vdt-ergonomia.svg"},{"asset":"idea-front-layout.svg"},{"asset":"idea-archive-safe.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - rischi quotidiani sul lavoro","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb),
('v22:workers-medium','Rischio medio: interferenze, movimentazione e attrezzature','hazard_spotting','lavoratore rischio medio','Persone, materiali e attrezzature condividono lo stesso spazio mentre il lavoro cambia ritmo.','Individua interferenze, movimentazione, attrezzature e condizioni che richiedono segregazione o stop prima di iniziare.','[{"choice":"Separo flussi e controllo area/attrezzatura prima del compito","effect":"Interferenza ridotta"},{"choice":"Concordo verbalmente di fare attenzione","effect":"Controllo fragile"}]'::jsonb,'{"questions":["Quale interferenza va eliminata?","Quando serve segregazione?","Quale controllo fai sull’attrezzatura?"]}'::jsonb,'[{"asset":"idea-risk-cycle.svg"},{"asset":"video-safe-moves.svg"},{"asset":"idea-inspection-flow.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - movimentazione, trasporto e rischio","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb),
('v22:workers-high','Rischio alto: più pericoli simultanei e stop work','tabletop','lavoratore rischio alto','Una fase di lavoro combina energia, mezzi, quota/interferenze e pressione sui tempi.','Prima di partire, costruisci una sequenza di controlli e individua il primo cambiamento che deve far fermare il lavoro.','[{"choice":"Autorizzo il compito solo dopo aver chiuso le condizioni critiche e definito stop/escalation","effect":"Margine di sicurezza esplicito"},{"choice":"Parto dalla misura più facile da aggiungere","effect":"Rischi maggiori possono restare aperti"}]'::jsonb,'{"questions":["Quale rischio domina?","Quali attività non possono sovrapporsi?","Qual è la stop condition più importante?"]}'::jsonb,'[{"asset":"piramide-pericoli.svg"},{"asset":"procedura-operativa-5-fasi.svg"},{"asset":"stop-segnala-ripristina.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - rischi multipli e prevenzione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb),
('v22:workers-update','Aggiornamento lavoratori: cosa è cambiato davvero?','incident_analysis','lavoratore','Negli ultimi anni sono cambiati persone, attrezzature, procedure o layout, ma alcune abitudini sono rimaste identiche.','Parti da un near miss recente o plausibile: trova ciò che è cambiato, ciò che non è stato aggiornato e una misura concreta da verificare.','[{"choice":"Uso il near miss per cambiare una misura o una procedura e verifico l’effetto","effect":"Aggiornamento basato sull’esperienza"},{"choice":"Ripasso le vecchie regole senza legarle ai cambiamenti","effect":"Basso trasferimento"}]'::jsonb,'{"questions":["Qual è il cambiamento più importante?","Quale vecchia abitudine è diventata incoerente?","Che indicatore userai?"]}'::jsonb,'[{"asset":"idea-risk-cycle.svg"},{"asset":"idea-inspection-flow.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - imparare dagli incidenti e dai comportamenti","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb),
('v22:datore-base','Datore di lavoro: scegliere una misura che cambia il sistema','tabletop','datore di lavoro','Un problema ricorrente produce quasi incidenti e assenze, ma la soluzione proposta è un nuovo richiamo al personale.','Decidi se accettare la proposta o investire in una misura tecnica/organizzativa, assegnando risorse, responsabilità e verifica.','[{"choice":"Confronto alternative e finanzio la misura che riduce l’esposizione alla fonte","effect":"Decisione manageriale efficace"},{"choice":"Aumento controlli e richiami senza cambiare il sistema","effect":"Causa di fondo invariata"}]'::jsonb,'{"questions":["Quale informazione economica/tecnica ti serve?","Chi deve attuare la misura?","Come verifichi efficacia?"]}'::jsonb,'[{"asset":"idea-safety-system.svg"},{"asset":"idea-dvr-reading.svg"},{"asset":"organigramma-sicurezza.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - leadership e prevenzione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb),
('v22:datore-update','Aggiornamento datore: cambiamento organizzativo e DVR vivo','tabletop','datore di lavoro','L’azienda ha cambiato layout, turni e attrezzature ma documenti e controlli sono stati aggiornati solo in parte.','Stabilisci priorità di riesame, consultazione, risorse e verifica senza limitarti all’aggiornamento documentale.','[{"choice":"Parto dai cambiamenti reali e verifico esposizioni/controlli sul campo","effect":"Valutazione viva"},{"choice":"Aggiorno prima i documenti e controllo il campo in seguito","effect":"Possibile scollamento tra carta e lavoro"}]'::jsonb,'{"questions":["Quale cambiamento va verificato per primo?","Chi coinvolgi?","Quale evidenza dimostra che la misura funziona?"]}'::jsonb,'[{"asset":"idea-dvr-reading.svg"},{"asset":"idea-inspection-flow.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - gestione del cambiamento e prevenzione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb),
('v22:dirigente-base','Dirigente: tradurre direttive in organizzazione sicura','tabletop','dirigente','Una nuova commessa aumenta carichi, turni e interferenze; le direttive aziendali sono corrette ma non ancora tradotte in risorse e sequenze operative.','Organizza persone, tempi, mezzi, responsabilità e controlli affinché la direttiva diventi eseguibile senza scaricare il rischio sui preposti.','[{"choice":"Riprogetto risorse e priorità prima dell’avvio","effect":"Direttiva resa operativa"},{"choice":"Chiedo ai preposti di gestire localmente le criticità","effect":"Responsabilità organizzativa scaricata"}]'::jsonb,'{"questions":["Quale risorsa manca?","Che cosa deleghi e che cosa resta tuo?","Come verifichi l’attuazione?"]}'::jsonb,'[{"asset":"idea-safety-system.svg"},{"asset":"organigramma-sicurezza.svg"},{"asset":"idea-inspection-flow.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - leadership e organizzazione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb),
('v22:dirigente-update','Aggiornamento dirigente: indicatori, deviazioni e correzione','incident_analysis','dirigente','I controlli formali risultano completati, ma near miss e deviazioni operative stanno aumentando.','Leggi gli indicatori, trova dove l’organizzazione non sostiene più le procedure e definisci una correzione misurabile.','[{"choice":"Uso near miss, sopralluoghi e feedback per correggere risorse/processi","effect":"Miglioramento basato su segnali deboli"},{"choice":"Aumento le verifiche di conformità senza cambiare il processo","effect":"Possibile aumento della sola pressione"}]'::jsonb,'{"questions":["Quale indicatore anticipa l’incidente?","Che cosa deve cambiare nel processo?","Come misuri il miglioramento?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"idea-risk-cycle.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - imparare dagli errori","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb)
on conflict(stable_key) do update set title=excluded.title,scenario_type=excluded.scenario_type,role_focus=excluded.role_focus,intro=excluded.intro,prompt=excluded.prompt,decisions=excluded.decisions,debrief=excluded.debrief,visuals=excluded.visuals,media=excluded.media,sources=excluded.sources,active=true,updated_at=now();

insert into public.practice_labs_v22(stable_key,title,lab_type,objective,briefing,steps,checklist,critical_errors,stop_conditions,media,sources,requires_physical_validation) values
('v22:workers-general-lab','Laboratorio generale: Stop → segnala → ripristina','digital','Allenare il passaggio da riconoscimento del pericolo ad azione nel proprio ruolo.','Usare tre scene del proprio settore o fotografie preparate dal docente.','["individua pericolo","identifica esposti","decidi se puoi correggere in sicurezza","ferma/segnala quando necessario","indica figura da coinvolgere","definisci evidenza di ripristino"]'::jsonb,'["pericolo","esposti","ruolo","stop","segnalazione","ripristino"]'::jsonb,'["continuare in attesa di segnalare","improvvisare intervento tecnico fuori ruolo","riprendere senza verifica"]'::jsonb,'["rischio grave/immediato","intervento richiede competenza/autorizzazione non posseduta"]'::jsonb,'[{"kind":"video_hub","title":"Napo - sicurezza e prevenzione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:workers-low-lab','Rischio basso: audit del lavoro quotidiano','digital','Individuare e correggere rischi frequenti in uffici, servizi e ambienti a bassa pericolosità apparente.','Eseguire il micro-audit su una zona reale senza interferire con l’attività.','["osserva layout e passaggi","controlla VDT/postura","cerca cavi/prese/anomalie","verifica emergenza e ordine","identifica fattori organizzativi","scegli tre azioni","ricontrolla"]'::jsonb,'["ergonomia","cadute a livello","elettrico visivo","esodo","stress/ritmo","azioni"]'::jsonb,'["confondere basso rischio con nessun rischio","correggere solo postura","spostare il problema altrove"]'::jsonb,'["anomalia elettrica","via esodo compromessa"]'::jsonb,'[{"kind":"video_hub","title":"Napo - rischi in ufficio","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb,false),
('v22:workers-medium-lab','Rischio medio: pre-start con interferenze','hybrid','Allenare pianificazione prima di un compito con movimentazione, attrezzature e persone.','Usare una lavorazione reale ferma o una planimetria/scena simulata.','["definisci compito","mappa persone/mezzi/materiali","segrega flussi","controlla attrezzatura","simula una variazione","decidi stop/escalation","debriefing"]'::jsonb,'["interferenze","attrezzatura","movimentazione","segnali","stop","debriefing"]'::jsonb,'["coordinamento solo verbale","zona pedoni non definita","variazione non rivalutata"]'::jsonb,'["interferenza non eliminabile","attrezzatura anomala"]'::jsonb,'[{"kind":"video_hub","title":"Napo - movimentazione e trasporto","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"EU-OSHA/Napo","url":"https://www.napofilm.net/it"}]'::jsonb,false),
('v22:workers-high-lab','Rischio alto: autorizzazione al lavoro e stop condition','hybrid','Allenare una verifica pre-start strutturata su attività con più rischi simultanei.','Il docente introduce almeno un cambio di condizione dopo l’autorizzazione iniziale.','["scomponi il lavoro in fasi","identifica rischio dominante","controlla protezioni/isolamenti","coordina interferenze","definisci stop condition","autorizza avvio","introduci variazione","ferma e rivaluta"]'::jsonb,'["fasi","rischio dominante","barriere","interferenze","stop","rivalutazione"]'::jsonb,'["partire con gap noto","affidarsi al DPI come unica barriera","proseguire dopo variazione non valutata"]'::jsonb,'["barriera critica assente","scenario diverso dal previsto","comunicazione persa"]'::jsonb,'[{"kind":"video_hub","title":"Napo - rischi multipli","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:workers-update-lab','Aggiornamento lavoratori: laboratorio near miss','digital','Trasformare un quasi incidente in una modifica concreta del lavoro.','Usare un near miss reale anonimizzato oppure uno scenario plausibile.','["ricostruisci fatti","separa cause immediate e sistemiche","individua barriera mancata","proponi correzione","assegna responsabile","definisci verifica","condividi lezione appresa"]'::jsonb,'["fatti","cause","barriere","azione","responsabile","verifica"]'::jsonb,'["cercare colpe","fermarsi a distrazione/errore umano","azione generica"]'::jsonb,'["informazioni insufficienti per concludere"]'::jsonb,'[{"kind":"video_hub","title":"Napo - imparare dagli incidenti","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:datore-base-lab','Datore: business case della prevenzione','digital','Prendere una decisione di investimento sicurezza confrontando efficacia, fattibilità e rischio residuo.','Usare un problema reale o scenario con almeno tre alternative.','["definisci esposizione","quantifica frequenza/gravità qualitativamente","genera tre alternative","ordina secondo gerarchia misure","assegna budget/responsabile","definisci scadenza","scegli indicatore di efficacia"]'::jsonb,'["problema","alternative","gerarchia","risorse","responsabile","indicatore"]'::jsonb,'["scegliere solo costo minore","nessuna verifica","delegare senza risorse"]'::jsonb,'["rischio residuo non accettabile"]'::jsonb,'[{"kind":"video_hub","title":"Napo - leadership e prevenzione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:datore-update-lab','Datore aggiornamento: management of change','digital','Verificare che un cambiamento aziendale non renda obsolete valutazioni e misure.','Scegliere un cambiamento recente: layout, processo, attrezzatura, persone o turni.','["descrivi prima/dopo","mappa nuovi esposti/interferenze","verifica DVR/procedure/formazione","definisci misure mancanti","assegna risorse","controlla sul campo","chiudi solo con evidenza"]'::jsonb,'["cambiamento","esposti","documenti","misure","risorse","campo","chiusura"]'::jsonb,'["aggiornare solo documenti","chiudere senza sopralluogo","nessun owner"]'::jsonb,'["cambiamento già operativo con barriera critica mancante"]'::jsonb,'[{"kind":"video_hub","title":"Napo - gestione del cambiamento","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:dirigente-base-lab','Dirigente: pianificazione sicura della commessa','digital','Tradurre obiettivi e direttive in un piano con risorse, sequenze e controlli.','Usare una commessa/progetto con almeno due funzioni coinvolte.','["definisci obiettivo","mappa attività e interferenze","assegna responsabilità","verifica competenze/risorse","stabilisci priorità","definisci controllo intermedio","riesamina con feedback preposti"]'::jsonb,'["interferenze","ruoli","risorse","priorità","controlli","feedback"]'::jsonb,'["piano senza risorse","responsabilità ambigue","nessun feedback dal campo"]'::jsonb,'["risorsa critica assente","interferenza non governata"]'::jsonb,'[{"kind":"video_hub","title":"Napo - leadership e organizzazione","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:dirigente-update-lab','Dirigente aggiornamento: dashboard dei segnali deboli','digital','Usare near miss, deviazioni e segnalazioni per decidere correzioni organizzative.','Costruire una mini-dashboard con dati reali anonimizzati o dataset simulato.','["raccogli 5 indicatori","distingui leading/lagging","trova trend","collega trend a processo","decidi azione","assegna owner","verifica dopo periodo definito"]'::jsonb,'["indicatori","trend","causa processo","azione","owner","verifica"]'::jsonb,'["guardare solo infortuni","premiare assenza di segnalazioni","azione senza criterio di successo"]'::jsonb,'["trend indica barriera critica degradata"]'::jsonb,'[{"kind":"video_hub","title":"Napo - imparare dagli errori","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false)
on conflict(stable_key) do update set title=excluded.title,lab_type=excluded.lab_type,objective=excluded.objective,briefing=excluded.briefing,steps=excluded.steps,checklist=excluded.checklist,critical_errors=excluded.critical_errors,stop_conditions=excluded.stop_conditions,media=excluded.media,sources=excluded.sources,requires_physical_validation=excluded.requires_physical_validation,active=true,updated_at=now();

with map(course_key,scenario_key,lab_key,is_update) as (values
('generale','v22:workers-general','v22:workers-general-lab',false),
('lav_basso','v22:workers-low','v22:workers-low-lab',false),('lav_medio','v22:workers-medium','v22:workers-medium-lab',false),('lav_alto','v22:workers-high','v22:workers-high-lab',false),('agg_lav','v22:workers-update','v22:workers-update-lab',true),
('dl_base','v22:datore-base','v22:datore-base-lab',false),('agg_dl','v22:datore-update','v22:datore-update-lab',true),
('dirigente','v22:dirigente-base','v22:dirigente-base-lab',false),('agg_dir','v22:dirigente-update','v22:dirigente-update-lab',true)
)
insert into public.course_scenarios_v22(course_id,scenario_id,position,required,context)
select c.id,s.id,2,true,jsonb_build_object('assigned_by','v22_005','specific',true,'update_course',m.is_update)
from map m join public.courses c on c.stable_key=m.course_key join public.training_scenarios_v22 s on s.stable_key=m.scenario_key
where c.active and coalesce(c.metadata->>'freeze_scope','')=''
on conflict(course_id,scenario_id) do update set position=excluded.position,required=true,context=excluded.context;
with map(course_key,scenario_key,lab_key,is_update) as (values
('generale','v22:workers-general','v22:workers-general-lab',false),
('lav_basso','v22:workers-low','v22:workers-low-lab',false),('lav_medio','v22:workers-medium','v22:workers-medium-lab',false),('lav_alto','v22:workers-high','v22:workers-high-lab',false),('agg_lav','v22:workers-update','v22:workers-update-lab',true),
('dl_base','v22:datore-base','v22:datore-base-lab',false),('agg_dl','v22:datore-update','v22:datore-update-lab',true),
('dirigente','v22:dirigente-base','v22:dirigente-base-lab',false),('agg_dir','v22:dirigente-update','v22:dirigente-update-lab',true)
)
insert into public.course_practice_labs_v22(course_id,practice_lab_id,position,required,context)
select c.id,l.id,2,true,jsonb_build_object('assigned_by','v22_005','specific',true,'update_course',m.is_update)
from map m join public.courses c on c.stable_key=m.course_key join public.practice_labs_v22 l on l.stable_key=m.lab_key
where c.active and coalesce(c.metadata->>'freeze_scope','')=''
on conflict(course_id,practice_lab_id) do update set position=excluded.position,required=true,context=excluded.context;

update public.course_scenarios_v22 cs set context=cs.context||'{"specific":true,"assigned_by":"v22_005_exact"}'::jsonb
from public.courses c where c.id=cs.course_id and c.stable_key in ('mod_cantieri','lav_quota','rls','agg_rls_4h','agg_rls_8h','preposto','agg_prep') and coalesce(c.metadata->>'freeze_scope','')='';
update public.course_practice_labs_v22 cp set context=cp.context||jsonb_build_object('specific',true,'assigned_by','v22_005_exact','update_course',c.stable_key in ('agg_rls_4h','agg_rls_8h','agg_prep'))
from public.courses c where c.id=cp.course_id and c.stable_key in ('mod_cantieri','lav_quota','rls','agg_rls_4h','agg_rls_8h','preposto','agg_prep') and coalesce(c.metadata->>'freeze_scope','')='';
